function getKbsToApply(finalMap) {
    const kbs_to_apply = [];

    for (const ip in finalMap) {
        const kbs = finalMap[ip]["kbList"] || [];
        kbs_to_apply.push(...kbs);
    }

    return kbs_to_apply;
};

$kbs_to_download = getKbsToApply($host_kb_and_sys_info_map)

const kbMetadataMap = {};
const kbs = [];

$HTTPRequest_1.result.value.forEach(item => {
  const kbArticles = item.kbArticles || [];

  kbArticles.forEach(article => {
    let kbNumber = null;

    if (article.downloadUrl) {
      const match = article.downloadUrl.match(/KB\d+/i);
      if (match) {
        kbNumber = match[0].toUpperCase();
      }
    }

    if (!kbNumber) {
      return;
    }

    kbs.push(kbNumber)
  });
});
$kbs_to_download.push(...kbs);
$kbs_to_download = [...new Set($kbs_to_download)];

const html = $get_download_catalog.result;

const updateIdRegex = /<input id="([0-9a-f\-]{36})"\s+class="flatBlueButtonDownload[^"]*"/g;

let match;
const ids = [];
while ((match = updateIdRegex.exec(html)) !== null) {
    ids.push(match[1]);
}

if (!Array.isArray($update_ids)) {
    $update_ids = [];
}

$update_ids.push(...ids);
$update_ids = [...new Set($update_ids)];

const htm = $HTTPRequest_4.result;

if (typeof $kb_details_map !== 'object' || $kb_details_map === null) {
  $kb_details_map = {};
}

const result = {
  title: htm.match(/<span id="ScopedViewHandler_titleText">\s*([^<]*)<\/span>/)?.[1].trim() || null,
  architecture: htm.match(/<div id="archDiv">\s*<span[^>]*>Architecture:<\/span>\s*([^<\n]*)/i)?.[1].trim() || null,
  classification: htm.match(/<div id="classificationDiv">\s*<span[^>]*>Classification:<\/span>\s*([^<\n]*)/i)?.[1].trim() || null,
  supported_products: htm.match(/<div id="productsDiv">\s*<span[^>]*>Supported products:<\/span>\s*([^<\n]*)/i)?.[1].trim() || null,
  kb_article: htm.match(/<div id="kbDiv"[^>]*>\s*<span[^>]*>KB article numbers:<\/span>\s*([^<\n]*)/i)?.[1].trim() || null
};

$kb_details_map[$ForEach_3.item] = result;

const htmlText = $HTTPRequest_3.result;
const kb_metadata = $kb_details_map[$ForEach_2.item];

if (typeof $kb_download_url_filename_map === 'undefined' || !Array.isArray($kb_download_url_filename_map)) {
  $kb_download_url_filename_map = [];
}

const kb_number = "KB" + kb_metadata.kb_article;
const titleRaw = kb_metadata.title;

function sanitizeFileName(title) {
  return title
    .replace(/\s+/g, "_")
    .replace(/[()]/g, "")
    .replace(/[^a-zA-Z0-9_\-().]/g, "")
    .substring(0, 150);
}

const downloadresmatch = htmlText.match(/downloadInformation\[0]\.files\[0]\.url\s*=\s*'([^']+)'/);

if (downloadresmatch && downloadresmatch[1] && titleRaw) {
  const fileUrl = downloadresmatch[1];
  const extensionMatch = fileUrl.match(/\.([a-zA-Z0-9]+)(?:\?|$)/);
  const extension = extensionMatch ? "." + extensionMatch[1] : "";
  const fileName = sanitizeFileName(titleRaw) + extension;

  $kb_download_url_filename_map.push({
      url: fileUrl,
      fileName: fileName,
      kbNumber: kb_number
    })
}
